import{n as m,t as l}from"./chunk-Da4-SChG.js";import{t as c}from"./chunk-BkyHaCPl.js";var t=(a,e,n,d,h,c,u,p=0)=>({id:a,x:e,y:n,z:d,width:h,height:c,depth:u,rotation:p});var S={schemaVersion:`1.0`,projectId:`calendar-monument`,version:`1.0.0`,template:{id:`engineering-design`,version:`1.0`},title:`From Sundial to Sun Monument`,mission:`Build a sundial, investigate its seasonal shadows, and explain Earth’s tilt. Your final project is a solar calendar: a stone monument with openings and colored jewels that marks the equinoxes and solstices.`,simulationId:`simulation.solar-monument`,designSamples:[{id:`solar-calendar-circle`,title:`Solar calendar circle`,description:`Start your final project with a Stonehenge-inspired circle of eight stone gates. Amber, blue and ruby jewels fill holes in three lintels. Find the moving light patches and place your own seasonal markers.`,design:c},{id:`sun-gate`,title:`Sun gate`,description:`Two pillars and a lintel frame a bright opening. Move the Sun to stretch the gate’s shadow and watch the gap travel across the ground.`,design:{blocks:[t(`gate-west`,-.55,0,0,.22,1.2,.28),t(`gate-east`,.55,0,0,.22,1.2,.28),t(`gate-lintel`,0,1.2,0,1.32,.24,.28)],targets:[{id:`gate-marker`,label:`Gate opening`,x:0,z:-.65}]}},{id:`round-portal`,title:`Round portal`,description:`A wide wall with an 80 cm cylindrical opening casts a dark frame around a patch of sunlight. Compare the patch at low and high Sun angles.`,design:{blocks:[m(l({},t(`portal`,0,0,0,1.4,1.2,.12)),{aperture:{axis:`z`,diameter:.8,insert:`open`,color:`clear`}})],targets:[{id:`portal-marker`,label:`Light through the hole`,x:0,z:-.5}]}},{id:`color-windows`,title:`Three color windows`,description:`Ruby, sapphire and amber windows paint moving patches on the ground. A pale crystal catches the middle beam. Try solar noon, then Inspect sculpture.`,design:{blocks:[`red`,`blue`,`amber`].flatMap((a,e)=>{let n=(e-1)*.75;return[t(`${a}-left`,n-.25,0,0,.1,.3,.14),t(`${a}-right`,n+.25,0,0,.1,.3,.14),m(l({},t(`${a}-window`,n,.3,0,.6,1,.08)),{aperture:{axis:`z`,diameter:.4,insert:e===1?`jewel`:`glass`,color:a}})]}),targets:[{id:`ruby-marker`,label:`Ruby patch`,x:-.75,z:-.65},{id:`amber-marker`,label:`Amber patch`,x:.75,z:-.65}],displayObject:{model:`crystal`,material:`porcelain`,x:0,y:0,z:-.55,width:.28,height:.5,rotation:0}}},{id:`pierced-pyramid`,title:`Pierced pyramid`,description:`Four terraces share a vertical tunnel. Can a high summer Sun send light all the way down? Use Plan view to inspect the hole and compare June with December.`,design:{blocks:[1.6,1.2,.8,.4].map((a,e)=>m(l({},t(`terrace-${e}`,0,e*.2,0,a,.2,a)),{aperture:{axis:`y`,diameter:.3,insert:`open`,color:`clear`}})),targets:[{id:`pyramid-marker`,label:`Inside the tunnel`,x:0,z:-.1}]}},{id:`shadow-crown`,title:`Shadow crown`,description:`Eight pillars surround a round sculpture. Their long and short shadows form spokes. Tiny holes in the taller pillars admit light only from some directions.`,design:{blocks:Array.from({length:8},(a,e)=>{let n=e*Math.PI/4;return l(l({},t(`crown-${e}`,.9*Math.sin(n),0,.9*Math.cos(n),.18,e%2?.7:1.1,.26,e*45)),e%2?{}:{aperture:{axis:`z`,diameter:.12,insert:`open`,color:`clear`}})}),targets:[{id:`crown-marker`,label:`Between the spokes`,x:.35,z:-.4}],displayObject:{model:`sphere`,material:`limestone`,x:0,y:0,z:0,width:.5,height:.5,rotation:0}}},{id:`twin-tunnels`,title:`Twin tunnels`,description:`These blocks have equal 32 cm holes but different depths: 10 cm and 65 cm. Find a Sun angle that lights one hole while the other stays dark.`,design:{blocks:[-.48,.48].map((a,e)=>m(l({},t(`tunnel-${e}`,a,0,0,.6,1.1,e?.65:.1)),{aperture:{axis:`z`,diameter:.32,insert:`open`,color:`clear`}})),targets:[{id:`thin-marker`,label:`Thin wall`,x:-.48,z:-.5},{id:`deep-marker`,label:`Deep tunnel`,x:.48,z:-.5}]}}],learningSequence:{practiceDesign:{blocks:[{id:`practice-post`,x:0,y:0,z:0,width:.08,depth:.08,height:.6,rotation:0}],targets:[]},steps:[{id:`make-a-sundial`,title:`Build a sundial`,workspace:`practice`,activity:`sundial-build`,showGuides:!1,introduction:`Can a shadow tell the time? Start with a vertical post on a level stone dial.`,instructions:[`Choose your place in Events & time. Open Build, set the post height to match your classroom model, and build your sundial.`,`Press Play day. Pause in the morning, near noon, and in the afternoon. Use Mark time to leave a mark at the shadow tip.`,`Play the same day again. Watch the shadow revisit your marks. Save a test when you are ready.`],question:{researchId:`daily-sun`,prompt:`What pattern did you notice as your sundial’s shadow moved through one day?`}},{id:`season-surprise`,title:`A seasonal surprise`,workspace:`practice`,activity:`sundial-seasons`,showGuides:!1,introduction:`Keep the same sundial and its original marks. Now change the season. Why do you think the shadow tip misses the old marks?`,instructions:[`The canvas starts on a different seasonal date. Your post and old marks stay in place.`,`Use Events & time to compare June and December at Solar noon. Then Play day on each date and watch where the shadow tip travels.`,`Notice the height of the Sun, shadow length, and daylight hours. Write your idea before continuing.`],question:{researchId:`season-noticing`,prompt:`The sundial did not move. Why do you think its shadow tip misses some old marks now? What did you observe?`}},{id:`explain-the-tilt`,title:`Why the shadows change`,workspace:`practice`,activity:`sundial-tilt`,introduction:`Connect your sundial observations to a turning, tilted Earth.`,instructions:[`In this Guide, choose Earth’s tilt. Find your site and the tilted axis. Play day to see Earth turn.`,`Change between June and December. The axis keeps pointing the same way as Earth travels around the Sun.`,`At Solar noon, compare the Sun’s height and your post’s shadow. How does the new model help explain your first idea?`],explanation:`Earth’s daily turn makes the Sun appear to cross the sky. Earth’s axis is tilted about 23.4° and keeps pointing nearly the same way as Earth orbits the Sun. This changes the Sun’s daily path and daylight duration at your site. A higher Sun gives a shorter shadow; a lower Sun gives a longer one. Northern and southern places have opposite seasons. Our simple dial uses a vertical post and fixed shadow-tip marks. More advanced sundials use a tilted pointer to keep their hour lines useful through the year. Clock time and solar time can also differ, so use solar noon for a fair seasonal comparison.`,question:{researchId:`seasons`,prompt:`Revise your explanation: how does Earth’s tilt help explain the seasonal change in your sundial’s shadows?`}},{id:`mark-the-year`,title:`Mark the sundial’s year`,workspace:`practice`,activity:`sundial-calendar`,introduction:`First challenge: make your sundial mark the equinoxes and solstices.`,instructions:[`Choose each special date from Events & time. At Solar noon, use Mark date to place its shadow-tip marker.`,`Compare all four marks. Which are closest together? Which dates have the shortest and longest noon shadows at your site?`,`Try a week before and after a special date. Does one marker identify an exact day or a range of days?`],explanation:`At an equinox the Sun crosses the celestial equator. March and September have similar Sun paths, so their noon marks are close. Solstices mark the yearly extremes in the Sun’s path. In the tropics, the highest noon Sun can occur on other dates. A shadow covering a mark is only part of the evidence: compare the tip and nearby dates too.`,question:{researchId:`dial-calendar`,prompt:`Which marks help your sundial show the time of year? Explain the equinox pair and why a solstice can be hard to identify to one exact day.`}},{id:`sun-monument`,title:`Build a solar calendar`,workspace:`project`,activity:`monument`,introduction:`Your final project is a solar calendar: a monument that marks the year with light and shadow. Take inspiration from Stonehenge’s standing stones, then invent your own openings and colored jewels.`,instructions:[`Open Build to arrange your stone circle. For a starting model, choose ••• → Sample models → Solar calendar circle → Use model. Your practice sundial stays saved.`,`Use pillars and lintels, cylindrical holes, and colored glass or jewels. Open Markers, choose Place on the floor, and click a light patch or shadow. Name your sunstone and Carve marker to save its position, date, time and Sun angle.`,`Keep one location. Use Events & time and Play day to find a useful observation time. Move, rotate, or resize your stones and openings until the light reaches your targets.`,`Select a saved sunstone to compare its recorded light with the light now. Show recorded Sun returns to its original observation. Use for a special date sets up its final test. Then choose ••• → Final demonstration and Compare to check all four dates and nearby days. Revise your calendar and Save comparison.`],explanation:`A successful solar calendar has a repeatable alignment and evidence for all four special dates. March and September can share one alignment. Some nearby dates may match too; explain this honestly. Stonehenge inspires the stone-circle idea. Our jeweled openings are a modern invention, and the example uses solar noon at Colorado Springs. Calibrate your own calendar for your chosen place and time.`}]},research:[{id:`season-noticing`,title:`The sundial surprise`,explanation:`Keep your first explanation so you can compare it with your thinking after exploring the Earth model.`,prompt:`Your sundial did not move. Why did its shadow tip miss old marks when the season changed?`,source:{label:`Explore a sundial · NASA`,url:`https://pwg.gsfc.nasa.gov/stargaze/Sdial1.htm`}},{id:`dial-calendar`,title:`A sundial that marks the year`,explanation:`A shadow tip can show a daily pattern and a yearly pattern. Two dates can have similar shadow positions; a marker alone does not always identify one unique date.`,prompt:`Compare your sundial’s four solar-noon marks and nearby dates. Which dates are hardest to distinguish?`,source:{label:`How sundials use Earth’s axis · Royal Museums Greenwich`,url:`https://www.rmg.co.uk/stories/time/sundials`}},{id:`daily-sun`,title:`A shadow moves`,explanation:`Earth rotates. The Sun appears to move across our sky, and a shadow points away from it. Sun altitude means its angle above the horizon; azimuth means its compass direction.`,prompt:`Measure a stick’s shadow at three times. Record the stick height, date, times, lengths, and directions. What changed?`,source:{label:`Explore Sun angles and solar noon · NOAA`,url:`https://www.gml.noaa.gov/grad/solcalc/glossary.html`}},{id:`seasons`,title:`The angle of a season`,explanation:`Earth’s axis stays tilted as Earth travels around the Sun. This changes the Sun’s height and daylight duration through the year. The two hemispheres experience opposite seasons.`,prompt:`Draw or describe how Earth’s tilt changes sunlight. At our location, how will solar-noon shadows differ in June and December?`,source:{label:`What causes the seasons? · NASA`,url:`https://spaceplace.nasa.gov/seasons/en/`}},{id:`moon`,title:`The Moon keeps a different rhythm`,explanation:`The Moon reflects sunlight. Its phases repeat in about 29.5 days as our view of its sunlit half changes. It can appear during the day. Ordinary Moon phases are not Earth’s shadow.`,prompt:`Compare the Moon on four dates about a week apart. Record phase, illumination, time, and position. Could a Moon calendar work like a solar calendar?`,source:{label:`Moon phases · NASA`,url:`https://science.nasa.gov/moon/moon-phases/`}},{id:`calendar`,title:`A building that marks time`,explanation:`A solstice marks an extreme in the Sun’s yearly path. At an equinox the Sun crosses the celestial equator. Equinox daylight is approximately, rather than exactly, twelve hours. Both equinoxes have similar Sun paths.`,prompt:`Research a solar monument such as Stonehenge. What alignment is documented? Sketch your own design and explain what it could tell an observer.`,source:{label:`Stonehenge and the solstice · English Heritage`,url:`https://www.english-heritage.org.uk/visit/places/stonehenge/things-to-do/solstice`}},{id:`colored-light`,title:`Build with light and color`,explanation:`A hole is a tunnel: a ray must clear both openings to pass through. A colored transparent material transmits some colors of light and absorbs others. A sculpture’s faces look different as the light direction changes.`,prompt:`Compare an empty hole, a colored window, and a deeper hole at the same Sun angle. Predict which sculpture faces will catch the color in March, June, September, and December. Which prediction does your evidence support?`,source:{label:`Color filters absorb parts of white light · Exploratorium`,url:`https://annex.exploratorium.edu/xref/exhibits/color_removal.html`}}],designBrief:`Build a solar calendar inspired by Stonehenge. Arrange standing stones and lintels into your own monument, then use cylindrical openings and colored jewels or glass to send light onto seasonal markers. Include a plan for June, December, and the shared equinox alignment. The stone-circle starter has openings but no markers: locating and testing them is your challenge. Match your classroom model’s dimensions, level base and true-north orientation.`,testInstructions:[`Choose your actual location on the globe or enter its latitude and longitude. Keep this location fixed for your first comparison.`,`Build your monument, make a prediction, then choose Show Sun. Use See shadows to look behind the stones. Play day follows this date from sunrise to sunset; pause when a pattern appears.`,`Choose March equinox, then Solar Noon. Solar noon is not always 12:00 on a clock. Predict the result, then save a trial.`,`Repeat for June solstice, September equinox, and December solstice. Select Solar Noon again after changing the date.`,`Open Markers → Place on the floor. Click a patch of light or shadow, name the sunstone, then Carve marker. The saved record includes the ground point, date, time, place, Sun height and compass direction, and light at its centre. Place by measurements provides an alternative using centimetres.`,`Try Shape the light in Build: add a supported light window, choose a colored glass or jewel insert, and place a sculpture behind it. Use Inspect sculpture and turn the camera to see the face catching the light.`,`Measure the opening diameter, its axis, and the block depth. Rotate the block to aim the tunnel. Change the date and time to find when colored light reaches a ground target or sculpture face. Colored filters in this model do not focus light like a curved lens.`,`Choose Solar noon, then compare June and December. Open Guide → Earth’s tilt to connect the changing shadow to Earth’s fixed tilt and orbit. In Final demonstration → Compare, choose a target, expectation and time for each date. Test a week before and after: does the marker identify one day or a range? Shadows change slowly near a solstice.`,`Revise the design and record another trial. Earlier designs remain in the evidence notebook.`,`Open Final demonstration. Choose a target and expected sunlight, shadow, or colored light for each equinox and solstice. Walk through all four dates on the same 3D model, compare the target outcomes and sculpture surface samples, then record the final comparison.`,`Check the physical model outdoors today at the matching time. Measure its shadow, compare with the simulation, and record differences. Observe shadows; never look directly at the Sun.`],exhibitPrompts:[`Introduce your solar calendar. Show how its stone openings and colored jewels or glass create repeatable seasonal alignments.`,`Explain Earth’s tilt, the changing Sun angle, and why your monument’s shadows change.`,`Describe the block dimensions, location, true-north orientation, target positions, and observation times needed to reproduce your design.`,`Use evidence from all four seasonal dates. Explain why the two equinoxes share an approximate alignment.`,`Describe a revision and what your nearby-date and outdoor tests taught you. Explain the limits of your model.`,`Compare the Moon’s monthly pattern with the Sun’s yearly pattern and credit your research sources.`],starterDesign:c};export{S as calendarMonumentConfig};